<script src="https://cdn.jsdelivr.net/npm/owl.carousel@2.3.4/dist/owl.carousel.min.js"></script>
<script>
$('.service-slider').each(function () {

    let $slider = $(this);
    let itemCount = $slider.find('.item').length;

    let sliderOptions = {
        margin: 5,
		stagePadding: 0,
		slideBy: 1,
        nav: false,
        dots: false,
		singleItem: true,
        autoplay: itemCount > 1, 
        smartSpeed: 700,
        loop: itemCount > 1,   
        responsive: {
            0:  { items: itemCount > 1 ? 3 : 1 },
            350:{ items: itemCount > 1 ? 3 : 1 },
            600:{ items: itemCount > 1 ? 3.5 : 1 },
            768:{ items: itemCount > 1 ? 3.5 : 1 },
            992:{ items: itemCount > 1 ? 3.5 : 1 }
        }
    };

    $slider.owlCarousel(sliderOptions);
});
</script>

<script>
function prescriptionsearchmodal() {
	$(".medication_detail_table").hide();
	$('#medicationTableBody').html("");
	$('#searchMedication').val("");
}
function closeprescriptionsearch() {
	document.body.style.overflow = '';
	$("#prescription-search-modal").hide();
}
function close_support_team() {
	document.body.style.overflow = '';
	$("#dash-semaglutide-alert").hide();
}
function alert_function(modal_id){
	$("#"+modal_id).css("display","flex");
}
function acknowledgedFun() {
	
	showLoaderPageLoad('show');
	 $.ajax({
            url: "{{ url('update-acknowledge') }}",
                type: "POST",
                data: {
                    _token: "{{ csrf_token() }}",
                    subscription_id: "1",
                },
                success: function(response) {
					
                    showLoaderPageLoad('hide');
					document.body.style.overflow = '';
					$("#dash-notification-pupdate").hide();
					
                },
                error: function(xhr) {
                    console.log("Error:", xhr.responseText);
                }
   });
   
}
function upgrade_alert_close(id=null) {
	if(id) {
		$("#"+id).css("display","none");
	} else {
		$("#upgrade-alert").hide();
	}
}
</script>
